using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.VisualBasic;
using DotNetAnalyzer.Analysis.Common;

namespace DotNetAnalyzer.Analysis.Vb;

/// <summary>
/// Loads VB.NET legacy projects via Roslyn.
///
/// Two paths:
///   1. <see cref="LoadAdhocAsync(string)"/> — globs *.vb in the project directory
///      (excluding autogenerated files via <see cref="AutogeneratedFileFilter"/>),
///      parses each into a syntax tree, builds a <see cref="VisualBasicCompilation"/>.
///      Used as fallback when MSBuildWorkspace is unavailable or fails.
///
///   2. MSBuild path is orchestrated by <c>ProjectAnalyzer.LoadCompilationsViaMSBuild</c>
///      (the workspace itself supports VB transparently); this loader exposes a helper
///      to filter syntax trees post-load via <see cref="StripAutogenerated(Compilation)"/>.
/// </summary>
public static class VbProjectLoader
{
    /// <summary>
    /// True if the current OS is Windows, where MSBuildWorkspace can resolve .vbproj
    /// legacy projects with full fidelity (requires VS Build Tools + VB workload).
    /// </summary>
    public static bool IsWindows =>
        System.Runtime.InteropServices.RuntimeInformation.IsOSPlatform(
            System.Runtime.InteropServices.OSPlatform.Windows);

    /// <summary>
    /// Builds a <see cref="VisualBasicCompilation"/> by globbing *.vb files in the
    /// directory containing <paramref name="projectPath"/> (or the directory itself
    /// if a directory is passed). Autogenerated files are filtered out.
    /// </summary>
    /// <returns>A compilation, or null if no parseable .vb files were found.</returns>
    public static Compilation? LoadAdhoc(string projectPath)
    {
        var directory = ResolveDirectory(projectPath);
        if (directory == null)
            return null;

        var allVbFiles = Directory.GetFiles(directory, "*.vb", SearchOption.AllDirectories);

        // Stable order is essential for determinism (Constitución IV).
        Array.Sort(allVbFiles, StringComparer.Ordinal);

        var nonAutogen = allVbFiles
            .Where(f => !AutogeneratedFileFilter.IsAutogenerated(f))
            .Where(f => !VbProjectContext.IsBuildOutput(directory, f))
            .ToArray();

        if (nonAutogen.Length == 0)
        {
            Console.Error.WriteLine($"[WARN] VbProjectLoader: no parseable .vb files in '{directory}' (after autogen filtering).");
            return null;
        }

        // 021 (FR-001, FR-002): the project file (the one given, or the first of the directory) supplies the root
        // namespace and the global imports of the compilation.
        var projectFile = File.Exists(projectPath) && projectPath.EndsWith(".vbproj", StringComparison.OrdinalIgnoreCase)
            ? projectPath
            : VbProjectContext.FindProjectFile(directory);
        var project = projectFile == null ? null : VbProjectFile.Load(projectFile);
        return Compile(nonAutogen, GuessAssemblyName(projectPath, directory), project, Array.Empty<MetadataReference>());
    }

    /// <summary>
    /// One Adhoc compilation per nested project file (021, research D2b): projects in topological order of their
    /// <c>ProjectReference</c>s (ties ordinal), each referencing the compilations before it; <c>.vb</c> files that
    /// belong to no project form a residual compilation. Autogenerated files and build outputs are skipped.
    /// </summary>
    public static IReadOnlyList<Compilation> LoadAdhocProjects(IReadOnlyList<string> projectFiles, string rootDirectory)
    {
        var projects = projectFiles
            .Select(VbProjectFile.Load)
            .OrderBy(p => p.Path, StringComparer.Ordinal)
            .ToList();
        var byPath = projects.ToDictionary(p => p.Path, p => p, StringComparer.Ordinal);

        // Deepest project directory owns a file.
        var allVbFiles = Directory.GetFiles(rootDirectory, "*.vb", SearchOption.AllDirectories);
        Array.Sort(allVbFiles, StringComparer.Ordinal);
        var filesByProject = projects.ToDictionary(p => p.Path, _ => new List<string>(), StringComparer.Ordinal);
        var residual = new List<string>();
        foreach (var file in allVbFiles)
        {
            if (AutogeneratedFileFilter.IsAutogenerated(file) || VbProjectContext.IsBuildOutput(rootDirectory, file))
                continue;
            var owner = projects
                .Where(p => VbProjectContext.IsSameOrUnder(Path.GetDirectoryName(file)!, p.Directory))
                .OrderByDescending(p => p.Directory.Length)
                .ThenBy(p => p.Path, StringComparer.Ordinal)
                .FirstOrDefault();
            if (owner == null)
                residual.Add(file);
            else
                filesByProject[owner.Path].Add(file);
        }

        var compilations = new List<Compilation>();
        var references = new List<MetadataReference>();
        foreach (var project in TopologicalOrder(projects, byPath))
        {
            var files = filesByProject[project.Path];
            if (files.Count == 0)
                continue;
            var compilation = Compile(files.ToArray(), Path.GetFileNameWithoutExtension(project.Path), project, references);
            compilations.Add(compilation);
            references.Add(compilation.ToMetadataReference());
        }

        if (residual.Count > 0)
        {
            var name = Path.GetFileName(rootDirectory.TrimEnd(Path.DirectorySeparatorChar));
            compilations.Add(Compile(residual.ToArray(), string.IsNullOrEmpty(name) ? "VbAdhocCompilation" : name, null, references));
        }

        return compilations;
    }

    private static IEnumerable<VbProjectFile> TopologicalOrder(List<VbProjectFile> projects, Dictionary<string, VbProjectFile> byPath)
    {
        var emitted = new HashSet<string>(StringComparer.Ordinal);
        var remaining = new List<VbProjectFile>(projects);
        while (remaining.Count > 0)
        {
            var next = remaining.FirstOrDefault(p => p.ProjectReferences
                .Where(byPath.ContainsKey)
                .All(emitted.Contains)) ?? remaining[0]; // cycle: ordinal order
            emitted.Add(next.Path);
            remaining.Remove(next);
            yield return next;
        }
    }

    private static Compilation Compile(string[] files, string assemblyName, VbProjectFile? project, IEnumerable<MetadataReference> projectReferences)
    {
        var trees = new List<SyntaxTree>();
        foreach (var file in files)
        {
            try
            {
                trees.Add(VisualBasicSyntaxTree.ParseText(File.ReadAllText(file), path: file));
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"[WARN] VbProjectLoader: could not parse '{file}': {ex.Message}");
            }
        }

        var references = AppDomain.CurrentDomain.GetAssemblies()
            .Select(a => a.Location)
            .Where(loc => !string.IsNullOrEmpty(loc) && File.Exists(loc))
            .Select(loc => (MetadataReference)MetadataReference.CreateFromFile(loc))
            .Concat(projectReferences)
            .ToArray();

        var options = new VisualBasicCompilationOptions(OutputKind.DynamicallyLinkedLibrary);
        if (project != null)
        {
            foreach (var diagnostic in project.Diagnostics)
                Console.Error.WriteLine($"[WARN] VbProjectFile: {diagnostic}");
            if (project.RootNamespace != null)
                options = options.WithRootNamespace(project.RootNamespace);
            var imports = new List<GlobalImport>();
            foreach (var import in project.GlobalImports)
            {
                try
                {
                    imports.Add(GlobalImport.Parse(import));
                }
                catch (ArgumentException)
                {
                    Console.Error.WriteLine($"[WARN] VbProjectFile: global import '{import}' of '{project.FileName}' ignored");
                }
            }

            if (imports.Count > 0)
                options = options.WithGlobalImports(imports);
        }

        return VisualBasicCompilation.Create(assemblyName, trees, references, options);
    }

    /// <summary>
    /// Async wrapper to align with MSBuildWorkspace API shape.
    /// </summary>
    public static Task<Compilation?> LoadAdhocAsync(string projectPath)
        => Task.FromResult(LoadAdhoc(projectPath));

    /// <summary>
    /// Returns a new compilation with autogenerated syntax trees removed.
    /// Use after MSBuildWorkspace.OpenProjectAsync to apply the same filter
    /// that the Adhoc path applies natively.
    /// </summary>
    public static Compilation StripAutogenerated(Compilation compilation)
    {
        var toRemove = compilation.SyntaxTrees
            .Where(t => AutogeneratedFileFilter.IsAutogenerated(t.FilePath))
            .ToArray();

        return toRemove.Length == 0
            ? compilation
            : compilation.RemoveSyntaxTrees(toRemove);
    }

    /// <summary>
    /// Emits a stderr warning when running on a non-Windows OS, where the MSBuild
    /// path for legacy .vbproj is unavailable. Idempotent; cheap to call once
    /// per VB project encountered.
    /// </summary>
    public static void WarnIfNonWindows()
    {
        if (IsWindows) return;
        Console.Error.WriteLine(
            "[WARN] OS is not Windows; .vbproj loading will use Adhoc fallback with reduced fidelity. " +
            "Full fidelity requires Visual Studio Build Tools 2019/2022 with VB workload on Windows.");
    }

    private static string? ResolveDirectory(string projectPath)
    {
        if (Directory.Exists(projectPath))
            return projectPath;

        if (File.Exists(projectPath))
            return Path.GetDirectoryName(projectPath);

        return null;
    }

    private static string GuessAssemblyName(string projectPath, string directory)
    {
        if (File.Exists(projectPath) &&
            projectPath.EndsWith(".vbproj", StringComparison.OrdinalIgnoreCase))
        {
            return Path.GetFileNameWithoutExtension(projectPath);
        }

        return Path.GetFileName(directory.TrimEnd(Path.DirectorySeparatorChar)) ?? "VbAdhocCompilation";
    }
}
